"""Provenance stamping for every results table (D090).

WHY THIS EXISTS
---------------
Three times in two days the same defect has shown up in a different place: a
generated artefact drifted out of step with its source and nothing said so.

  * D086 -- the placebo prompt set still carried a rejected vignette.
  * D087 -- the nuisance floor was five days stale and partly built from that
    same rejected vignette, and it gates every `exceeds_floor` in the study.
  * D090 (this file) -- six tables were never regenerated by the pipeline at
    all, one of them 11 days old, and NOTHING in the repository reported it.
    `src.stats.stamp()` wrote only `verification_status`, so no table carried
    any record of which prompt set produced it.

The common mechanism is that staleness was always *inferable* and never
*asserted*. The fix is to make every table state its own provenance, so a stale
table is a fact on disk rather than something a reader has to reconstruct from
file timestamps.

WHAT IS STAMPED
---------------
`prompt_hash` -- the hash of every field that changes what gets scored, from
`src.vignettes.prompt_set_hash`. A table whose stamp is not the current hash was
built from a prompt set that no longer exists and must not be read as a result.

A table with no `prompt_hash` column is reported as UNSTAMPED, which is not the
same as stale: it means its provenance is unknown, which for reporting purposes
is just as disqualifying.
"""

from __future__ import annotations

from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
TABLES = ROOT / "results/tables"
CSV = ROOT / "data/vignettes/vignettes.csv"
STAMP_COL = "prompt_hash"

# Tables whose inputs are NOT the prompt set, so a prompt-set stamp would be
# meaningless rather than informative. Each needs a stated reason.
NOT_PROMPT_DERIVED = {
    "rq1_corpus_skew.csv": "corpus counts, independent of the vignettes",
    "rq1_corpus_skew_decision.csv": "corpus counts",
    "rq1_corpus_skew_explicit.csv": "corpus counts",
    "rq1_corpus_skew_probe.csv": "corpus counts",
    "rq1_corpus_skew_probe_decision.csv": "corpus counts",
    "rq6_search_counts.csv": "literature search, not model output",
    "v_d_contamination.csv": "n-gram counts of GUIDELINE text in corpora; the "
                             "probes are guideline spans, not prompts",
    "i4_corpus_disagreement.csv": "corpus-to-corpus comparison",
    "doi_verification.json": "not a table",
}

# Prefixes exempt for the same reason. rq0_instrument_validation__* comes from
# scripts/validate_instrument.py, which scores ADMINISTRATIVE stimuli (record
# numbers, letter codes) with no clinical content and no vignette text at all --
# that is the whole point of D035, so the vignette prompt set cannot stale it.
NOT_PROMPT_DERIVED_PREFIX = ("rq0_instrument_validation__",)

_cache: str | None = None


def prompt_hash_now() -> str:
    """The current prompt-set hash, computed once per process."""
    global _cache
    if _cache is None:
        import sys
        sys.path.insert(0, str(ROOT))
        from src.vignettes import prompt_set_hash
        v = pd.read_csv(CSV)
        if "blocked_on" in v.columns:
            v = v[v["blocked_on"].fillna("").astype(str).str.strip() == ""]
        v = v[v["analysis_ready"] == True]            # noqa: E712
        _cache = prompt_set_hash(v)
    return _cache


def write_table(df: pd.DataFrame, dest: Path | str, **kwargs) -> Path:
    """Write a results table with its prompt-set provenance stamped in."""
    dest = Path(dest)
    out = df.copy()
    out[STAMP_COL] = prompt_hash_now()
    kwargs.setdefault("index", False)
    dest.parent.mkdir(parents=True, exist_ok=True)
    out.to_csv(dest, **kwargs)
    return dest


def scored_run_hashes() -> set:
    """Prompt-set hashes that have actually been SCORED, from the manifest."""
    import json
    out = set()
    for mf in (ROOT / "results").glob("raw*/manifest.json"):
        try:
            d = json.loads(mf.read_text())
        except Exception:                              # noqa: BLE001
            continue
        for r in d.get("runs", []):
            if r.get("prompt_hash"):
                out.add(r["prompt_hash"])
    return out


def audit(verbose: bool = True) -> int:
    """Report every table's provenance. Returns the number of bad tables."""
    cur = prompt_hash_now()

    # KNOWN LIMIT OF THE STAMP, stated rather than hidden. write_table() stamps
    # the hash of the prompt CSV AS IT IS WHEN THE TABLE IS WRITTEN -- not the
    # hash of the scored rows the numbers were computed from. So running stats
    # over stale raw output produces a table stamped CURRENT whose numbers are
    # not. The stamp cannot catch that on its own; this check can, because a
    # prompt set that was never scored cannot have produced any number.
    unscored = cur not in scored_run_hashes()
    stale, unstamped, ok, exempt = [], [], [], []
    for p in sorted(TABLES.glob("*.csv")):
        if p.name.startswith("_"):
            continue
        if (p.name in NOT_PROMPT_DERIVED
                or p.name.startswith(NOT_PROMPT_DERIVED_PREFIX)):
            exempt.append(p.name)
            continue
        try:
            cols = pd.read_csv(p, nrows=0).columns
        except Exception:
            unstamped.append((p.name, "unreadable"))
            continue
        if STAMP_COL not in cols:
            unstamped.append((p.name, "no prompt_hash column"))
            continue
        seen = set(pd.read_csv(p, usecols=[STAMP_COL])[STAMP_COL]
                   .dropna().astype(str))
        if seen == {cur}:
            ok.append(p.name)
        else:
            stale.append((p.name, ", ".join(sorted(seen)) or "empty"))

    # The deck generator (deck_src/figures.js) reads this file and refuses to
    # build if any table it uses carries a different hash. Node cannot recompute
    # the hash, so the audit publishes it (D090).
    import json as _json
    (TABLES / "_current_prompt_hash.txt").write_text(cur + "\n")
    (TABLES / "_provenance.json").write_text(_json.dumps(
        {"prompt_hash": cur, "scored": cur in scored_run_hashes()}, indent=2))

    if verbose:
        print(f"\ncurrent prompt set: {cur}")
        print(f"  {len(ok)} table(s) stamped CURRENT")
        if exempt:
            shown = exempt if len(exempt) <= 6 else exempt[:6] + [
                f"... and {len(exempt) - 6} more"]
            print(f"  {len(exempt)} table(s) exempt (not prompt-derived): "
                  f"{', '.join(shown)}")
        for name, got in stale:
            print(f"  !! STALE      {name}  built from {got}")
        for name, why in unstamped:
            print(f"  ?  UNSTAMPED  {name}  ({why})")
        if unscored:
            print(f"\n  !! THE CURRENT PROMPT SET HAS NEVER BEEN SCORED.")
            print(f"     {cur} matches no run in any results/raw*/manifest.json.")
            print( "     Every table above is stamped with this hash because "
                   "that is when it was")
            print( "     written -- but the numbers in it came from rows scored "
                   "under a DIFFERENT")
            print( "     prompt set. Treat all of them as stale until "
                   "src.score_outputs has run.")
        if stale or unstamped or unscored:
            print("\n   A stale or unstamped table states nothing about the "
                  "current prompt set and must not be cited, quoted in the "
                  "deck, or copied to the site (D090).")
    return len(stale) + len(unstamped) + (1 if unscored else 0)


if __name__ == "__main__":
    raise SystemExit(1 if audit() else 0)
